      `${source}/evidence/receipt.json`,
    ]
    const references = await Promise.all(
      files.map(async (origin) => ({
        origin,
        relocated: `${archive}${origin.slice(source.length)}`,
        sha256: sha(await readFile(join(root, origin))),
        kind: origin.endsWith('receipt.json') ? 'immutable-origin' : 'owned',
      })),
    )
    const args = {
      root,
      manifest: m,
      stageId: 'W01',
      date: '2026-10-02',
      operations,
      references,
      evidence,
      boundary,
      snapshot: snap,
      reader: createArtifactReader(root),
      expectedHead: baseline,
    }
    const statusBefore = git(root, 'status', '--porcelain')
    assert.ok(
      issue(await executeClosure({ ...args, evidence: { ...evidence, post: null } }), 'POST_PROOF'),
    )
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    assert.ok(
      issue(
        await executeClosure({
          ...args,
          operations: [
            ...operations.slice(0, 3),
            { ...operations[3], to: 'openspec/changes/archive/2026-10-02-foreign' },
          ],
        }),
        'ARCHIVE_DESTINATION',
      ),
    )
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    assert.ok(issue(await executeClosure({ ...args, date: '2026-2-2' }), 'ARCHIVE_DATE'))
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    const productDestination = structuredClone(m)
    productDestination.scope.closure.specDestinations = ['apps/site/spec.md']
    assert.ok(
      issue(await executeClosure({ ...args, manifest: productDestination }), 'CLOSURE_DESTINATION'),
    )
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    assert.ok(issue(await executeClosure({ ...args, expectedHead: '0'.repeat(40) }), 'GIT_STALE'))
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    let readerCalls = 0
    await executeClosure({
      ...args,
      expectedHead: '0'.repeat(40),
      reader: {
        read: async () => {
          readerCalls++
          throw new Error('untrusted reader invoked')
        },
      },
    })
    assert.equal(readerCalls, 0)
    assert.ok(
      issue(
        await executeClosure({
          ...args,
          operations: [{ ...operations[0], sourceSha256: H }, ...operations.slice(1)],
        }),
        'SOURCE_HASH',
      ),
    )
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    const broken = references.map((x) => ({ ...x }))
    broken.find((x) => x.origin.endsWith('design.md')).sha256 = H
    assert.ok(issue(await executeClosure({ ...args, references: broken }), 'REFERENCE_HASH'))
    assert.equal(git(root, 'status', '--porcelain'), statusBefore)
    await write(`${source}/design.md`, '[plan](missing.md)\n')
    await write(
      `${source}/role-authority.json`,
      JSON.stringify({
        roleAuthority: {
          path: 'design.md',
          sha256: sha(await readFile(join(root, `${source}/design.md`))),
        },
      }),
    )
    git(root, 'add', '--', `${source}/design.md`, `${source}/role-authority.json`)
    git(
      root,
      '-c',
      'user.name=Fixture',
      '-c',
      'user.email=fixture@example.invalid',
      'commit',
      '-qm',
      'broken reference',
    )
    const brokenLinkRefs = references.map((x) => ({ ...x }))
    brokenLinkRefs.find((x) => x.origin.endsWith('design.md')).sha256 = sha(
      await readFile(join(root, `${source}/design.md`)),
    )
    brokenLinkRefs.find((x) => x.origin.endsWith('role-authority.json')).sha256 = sha(
      await readFile(join(root, `${source}/role-authority.json`)),
    )
    assert.ok(
      issue(
        await executeClosure({
          ...args,
          references: brokenLinkRefs,
          expectedHead: git(root, 'rev-parse', 'HEAD'),
        }),
        'REFERENCE_BROKEN',
      ),
    )
    await write(`${source}/design.md`, '[plan](tasks.md)\n[foreign](../../../foreign.txt)\n')
    await write(
      `${source}/role-authority.json`,
      JSON.stringify({
        roleAuthority: {
          path: 'design.md',
          sha256: sha(await readFile(join(root, `${source}/design.md`))),
        },
      }),
    )
    git(root, 'add', '--', `${source}/design.md`, `${source}/role-authority.json`)
    git(
      root,
      '-c',
      'user.name=Fixture',
      '-c',
      'user.email=fixture@example.invalid',
      'commit',
      '-qm',
      'repair reference',
    )
    args.expectedHead = git(root, 'rev-parse', 'HEAD')
    const closed = await executeClosure(args)
    assert.equal(closed.ok, true, JSON.stringify(closed.issues))
    assert.match(
      await readFile(join(root, 'openspec/specs/engineering-role-dispatch/spec.md'), 'utf8'),
      /OLD-01 Keep/,
    )
    assert.match(
      await readFile(join(root, 'openspec/specs/engineering-role-dispatch/spec.md'), 'utf8'),
      /ENGINEERING-ROLE-DISPATCH-01 New/,
    )
    assert.match(
      await readFile(join(root, 'openspec/specs/engineering-progress-publication/spec.md'), 'utf8'),
      /ENGINEERING-PROGRESS-PUBLICATION-01 New/,
    )
    assert.match(
      await readFile(join(root, 'openspec/specs/engineering-progress-publication/spec.md'), 'utf8'),
      /## Requirements/,
    )
    assert.equal(
      await readFile(join(root, `${archive}/evidence/receipt.json`), 'utf8'),
      '{"raw":"immutable"}\n',
    )
    assert.equal(
      closed.receipt.origins.find((x) => x.origin.endsWith('receipt.json')).sha256,
      references.find((x) => x.origin.endsWith('receipt.json')).sha256,
    )
    assert.equal(
      await readFile(join(root, `${archive}/design.md`), 'utf8'),
      '[plan](tasks.md)\n[foreign](../../../../foreign.txt)\n',
    )
    assert.deepEqual(JSON.parse(await readFile(join(root, `${archive}/role.json`), 'utf8')), {
      source: `${archive}/tasks.md`,
    })
    assert.deepEqual(
      JSON.parse(await readFile(join(root, `${archive}/role-authority.json`), 'utf8')),
      {
        roleAuthority: {
          path: 'design.md',
          sha256: sha(await readFile(join(root, `${archive}/design.md`))),
        },
      },
    )
    assert.equal(await readFile(join(root, 'foreign.txt'), 'utf8'), 'unchanged')
    assert.equal(await readFile(join(root, 'apps/site/frozen.ts'), 'utf8'), 'frozen app')
    assert.equal(await readFile(join(root, 'packages/core/frozen.ts'), 'utf8'), 'frozen package')
    m.stages[0].phase = 'ARCHIVE'
    assert.ok(
      issue(
        await evaluateTransition({
          manifest: m,
          stageId: 'W01',
          target: 'CLOSED',
          evidence,
          boundary,
          snapshot: snap,
        }),
        'ARCHIVE_PROOF',
      ),
    )
    const archiveProof = {
      ...proof('archive'),
      bindings: {
        ...proof('archive').bindings,
        archiveHead: args.expectedHead,
        archive: closed.receipt.archive,
        operationSha256: closed.receipt.operationSha256,
        checkpointSha: 'c'.repeat(40),
        publishedSha: 'c'.repeat(40),
        publicationRef: 'refs/heads/codex/frade-standard-workflow',
      },
    }
    assert.ok(
      issue(
        await evaluateTransition({
          manifest: m,
          stageId: 'W01',
          target: 'CLOSED',
          evidence: { ...evidence, closureReceipt: closed.receipt, archive: archiveProof },
          boundary,
          snapshot: snap,
        }),
        'ARCHIVE_PROOF',
      ),
    )
    trusted.add(archiveProof)
    assert.ok(
      issue(
        await evaluateTransition({
          manifest: m,
          stageId: 'W01',
          target: 'CLOSED',
          evidence: {
            ...evidence,
            closureReceipt: closed.receipt,
            archive: {
              ...archiveProof,
              bindings: { ...archiveProof.bindings, publishedSha: 'd'.repeat(40) },
            },
          },
          boundary,
          snapshot: snap,
        }),
        'ARCHIVE_PUBLICATION',
      ),
    )
    assert.equal(
      (
        await evaluateTransition({
          manifest: m,
          stageId: 'W01',
          target: 'CLOSED',
          evidence: { ...evidence, closureReceipt: closed.receipt, archive: archiveProof },
          boundary,
          snapshot: snap,
        })
      ).ok,
      true,
    )
  } finally {
    await rm(root, { recursive: true, force: true })
  }
})

